import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {SessionStore} from '../../types/sessionStore.js';
import type {ChatSession} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';

const wire = (sent: OutgoingMessage[]): string[] =>
  sent.map(frame => {
    if (frame.type === 'session_list') return `session_list ${frame.sessions.length}`;
    if (frame.type === 'error') return `error ${frame.code}`;
    return frame.type;
  });

describe('list_sessions handling', () => {
  it('calls sessionStore.listFor and answers session_list', async () => {
    const orchestrator = {} as ChatOrchestrator;
    const sessions = [{sessionId: 's1', userId: 'u1', createdAt: new Date(), updatedAt: new Date()}];
    const listFor = jest.fn().mockResolvedValue(sessions);
    const sessionStore = {listFor} as unknown as SessionStore;

    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

    // @ts-expect-error - threading not yet implemented
    const handle = createMessageHandler(orchestrator, sessionStore);
    await handle(ws, session, {type: 'list_sessions'});

    expect(listFor).toHaveBeenCalledWith('u1', {limit: undefined, before: undefined});
    expect(wire(sent)).toEqual(['session_list 1']);
  });
});

